  const sign = milli < 0n ? '-' : '';
  const abs = milli < 0n ? -milli : milli;
  const int = abs / 1000n;
  const frac = (abs % 1000n).toString().padStart(3, '0');
  return `${sign}${int}.${frac}`;
}

